pendulum_00.shader:
float wood = smoothstep(0.58, 0.62, _surface.diffuseTexcoord.x);
_surface.metalness = mix(0.8, 0.0, wood);
_surface.roughness = mix(0.3, 0.48, wood);

defl_cellphone01.shader:
float2 uv = _surface.diffuseTexcoord;
float innerScreen = step(0.13,uv.x)*step(uv.x,0.46)*step(0.13,uv.y)*step(uv.y,0.39);
float outerScreen = step(0.70,uv.x)*step(uv.x,0.865)*step(0.225,uv.y)*step(uv.y,0.325);
float screen = max(innerScreen,outerScreen);
float3 c = _surface.diffuse.rgb;
float bright = smoothstep(0.2,0.5,min(c.r,min(c.g,c.b)));
float neutral = 1.0-smoothstep(0.02,0.12,max(c.r,max(c.g,c.b))-min(c.r,min(c.g,c.b)));
float trim = bright*neutral*(1.0-screen);
_surface.metalness = trim*0.8;
_surface.roughness = mix(mix(0.44,0.24,trim),0.10,screen);
_surface.clearCoat = mix(0.18,0.7,screen);
_surface.emission.rgb = c*screen*0.24;
